{
  "locale": "zh",
  "questions": [
    {
      "id": "t15-energy",
      "source_numbers": [
        "1"
      ],
      "intent": {
        "task": "利用初始电容储能与最终完全耗散求总热量。",
        "source_solution": "C=10^-8 F，初始电感电流为零，因此初始总能量为 q^2/(2C)。最终电磁储能为零且无外部输入，Q=10^-10/(2*10^-8)=0.005 J。",
        "unit_reason": "完整能量守恒计算是一个响应单位，不拆成电压或能量的中间数值槽。",
        "concept_blocks": [],
        "limitations": [
          "选择完整结果不能证明独立写出能量守恒推导。"
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "c"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "incorrect",
            "derivation": "漏掉 1/2，计算 q^2/C=10^-10/10^-8=0.010 J。",
            "misconception": "用电荷乘最终充电电压代替充电过程中电压积分得到的储能。"
          },
          {
            "option_id": "b",
            "truth": "incorrect",
            "derivation": "把 0.01 微法拉换算为 0.01*10^-3 F=10^-5 F，得到 q^2/(2C)=5*10^-6 J。",
            "misconception": "将微的换算因子 10^-6 错当成毫的 10^-3。"
          },
          {
            "option_id": "c",
            "truth": "correct",
            "derivation": "换算 C=10^-8 F，全部初始储能 q^2/(2C)=5*10^-3 J 转化为热量。",
            "misconception": null
          },
          {
            "option_id": "d",
            "truth": "incorrect",
            "derivation": "先得到总能量 0.005 J，再除以二，得到 0.0025 J。",
            "misconception": "将振荡中电场能的时间平均份额误当成最终耗散的总能量。"
          }
        ]
      }
    },
    {
      "id": "t15-dielectric-periods",
      "source_numbers": [
        "2"
      ],
      "intent": {
        "task": "从圆形极板几何计算电容，并比较完全填充前后的振荡周期。",
        "source_solution": "r=0.012 m，d=0.0003 m。按题面常数 C0=epsilon0*pi*r^2/d 约为 1.33518*10^-11 F。T0=2*pi*sqrt(0.003*C0) 约为 1.257508 微秒。填充后 C=4C0，周期变为 2T0 约 2.515016 微秒，三位有效数字数值对为 (1.26,2.52) 微秒。",
        "unit_reason": "同一回路的前后周期作为有序数值对，保留电容几何与介电常数平方根缩放的关系。",
        "concept_blocks": [],
        "limitations": [
          "选择完整数值对不能证明独立推导极板电容公式及写出两次周期计算。"
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "b"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "incorrect",
            "derivation": "正确算出 T0 约 1.257508 微秒，却直接乘介电常数 4，得到填充周期约 5.030032 微秒。",
            "misconception": "认为周期与电容成正比，而不是与电容平方根成正比。"
          },
          {
            "option_id": "b",
            "truth": "correct",
            "derivation": "极板面积为 pi*(0.012)^2，周期为 2*pi*sqrt(LC)。电容增大四倍使周期增大两倍，得到 (1.26,2.52) 微秒。",
            "misconception": null
          },
          {
            "option_id": "c",
            "truth": "incorrect",
            "derivation": "把 1.2 cm 半径误当成直径，取 r=0.006 m，面积和电容都缩小四倍，两次周期都减半，得到 (0.629,1.26) 微秒。",
            "misconception": "将给定半径再次除以二。"
          },
          {
            "option_id": "d",
            "truth": "incorrect",
            "derivation": "填充前周期正确，却认为填充使电容减小四倍，得到填充周期 T0/2 约 0.629 微秒。",
            "misconception": "颠倒相对介电常数对电容的作用方向。"
          }
        ]
      }
    },
    {
      "id": "t15-inductance-range",
      "source_numbers": [
        "3"
      ],
      "intent": {
        "task": "求完整电感区间，并保持频率与区间端点的正确对应。",
        "source_solution": "L=1/(4*pi^2*nu^2*C)。L400=0.0158314 H，L500=0.0101321 H。频率增加时电感减小，调节区间约为 [10.1,15.8] mH。",
        "unit_reason": "带方向的端点数值对同时表达区间和变化方向，不把两个相关端点拆成孤立计算。",
        "concept_blocks": [],
        "limitations": [
          "选择数值对不能证明独立变形得到频率与电感的关系式。"
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "d"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "incorrect",
            "derivation": "从正确的 L400=15.8314 mH 出发，误乘 500/400，得到 L500=19.7893 mH。",
            "misconception": "把电感当成与频率成正比。"
          },
          {
            "option_id": "b",
            "truth": "incorrect",
            "derivation": "算出了 10.1321 和 15.8314 mH 两个值，却把它们分别配给 400 和 500 Hz。",
            "misconception": "将反向关系中的两个频率端点对应颠倒。"
          },
          {
            "option_id": "c",
            "truth": "incorrect",
            "derivation": "从 15.8314 mH 出发，仅乘 400/500，得到 12.6651 mH。",
            "misconception": "只使用频率的一次反比，漏掉平方。"
          },
          {
            "option_id": "d",
            "truth": "correct",
            "derivation": "将两个频率分别代入 L=1/(4*pi^2*nu^2*10^-5)，得到有序数值对 (15.8,10.1) mH。",
            "misconception": null
          }
        ]
      }
    },
    {
      "id": "t15-rotating-loop-amplitude",
      "source_numbers": [
        "4"
      ],
      "intent": {
        "task": "从面积、磁感应强度和角速度计算感生电动势振幅。",
        "source_solution": "S=0.0100 m^2，omega=2*pi*50=100*pi rad/s，匝数为一。Em=nBS*omega=0.2*pi V 约为 0.628 V。",
        "unit_reason": "一个完整振幅结果同时要求面积与转速换算以及法拉第定律。",
        "concept_blocks": [],
        "limitations": [
          "选择结果不能证明独立对磁通量求时间导数。"
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "a"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "correct",
            "derivation": "Em=0.2*(100*10^-4)*(2*pi*50)=0.6283185 V。",
            "misconception": null
          },
          {
            "option_id": "b",
            "truth": "incorrect",
            "derivation": "把每秒 50 转误当成 50 rad/s，得到 Em=0.2*0.0100*50=0.100 V。",
            "misconception": "换算转速到角速度时漏掉 2*pi。"
          },
          {
            "option_id": "c",
            "truth": "incorrect",
            "derivation": "面积换算只乘 10^-2，将 100 cm^2 当成 1 m^2，得到 Em=0.2*1*100*pi 约 62.8 V。",
            "misconception": "对面积只使用一次长度换算因子。"
          },
          {
            "option_id": "d",
            "truth": "incorrect",
            "derivation": "将正确振幅 0.6283185 V 除以 sqrt(2)，得到 0.4442883 V。",
            "misconception": "把所求的振幅换成正弦电动势有效值。"
          }
        ]
      }
    },
    {
      "id": "t15-instantaneous-emf",
      "source_numbers": [
        "5"
      ],
      "intent": {
        "task": "联合判断瞬时电动势、初始磁通相位和明确选择的极性参考，区分通常垂直转轴模型的条件性计算与原始数据可确定的结论。",
        "source_solution": "在转轴垂直于 B 的条件下，nBS=0.300，omega=1.4/0.300=14/3 rad/s，lambda=0.300*cos(omega*t)，E=1.4*sin(omega*t)。于是 |E(0.1)|=0.6298766 V；指定环绕方向给出正值，反向参考给出负值。若转轴与 B 夹角为 alpha，则 Em=nBS*omega*sin(alpha)^2。alpha=45 度、omega=28/3 同样满足给定振幅和初始方向，却给出 |E(0.1)|=1.12505 V，因此原始条件不确定唯一无条件数值。",
        "unit_reason": "使用一个原生多选题共同判断大小与极性参考的关系及条件是否充分，不拆成数值槽或逐句是非按钮。",
        "concept_blocks": [],
        "limitations": [
          "原始题缺少转轴方向，无法给出唯一无条件瞬时电动势数值；垂直转轴的结果均显式作为条件性结论，不冒充源事实。",
          "没有端点约定或带标签的几何图，不能识别实际哪一导线端点为正。",
          "选择结论不能证明独立推导磁通量的时间函数。"
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "a",
          "c",
          "e"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "correct",
            "derivation": "在显式转轴条件下，Em=nBS*omega 给出 omega=14/3；1.4*abs(sin((14/3)*0.1))=0.6298766 V，两个数值均成立。",
            "misconception": null
          },
          {
            "option_id": "b",
            "truth": "incorrect",
            "derivation": "初始磁通最大，E=1.4*sin(0)=0 V，而不是 1.4 V。",
            "misconception": "因初始平面垂直于磁场而错误采用零初相的余弦电动势，混淆磁通最大与磁通导数最大。"
          },
          {
            "option_id": "c",
            "truth": "correct",
            "derivation": "正法向初始沿 B，故 lambda=+nBS*cos(omega*t)；E=-d(lambda)/dt=+Em*sin(omega*t)，且 sin(7/15) 为正。",
            "misconception": null
          },
          {
            "option_id": "d",
            "truth": "incorrect",
            "derivation": "环绕方向及其正法向反转，lambda 和 E 都变号，0.1 s 时应为 -0.6298766 V。",
            "misconception": "把带符号电压误认为在参考方向反转时不变。"
          },
          {
            "option_id": "e",
            "truth": "correct",
            "derivation": "固定斜转轴模型的 lambda=nBS*(cos(alpha)^2+sin(alpha)^2*cos(omega*t))，给定振幅只固定 omega*sin(alpha)^2=14/3。垂直转轴和 45 度转轴保留相同数据却产生不同瞬时电动势大小。",
            "misconception": null
          }
        ]
      }
    },
    {
      "id": "t15-inductor-current-amplitude",
      "source_numbers": [
        "6"
      ],
      "intent": {
        "task": "使用感抗求电流，并区分有效值和振幅。",
        "source_solution": "XL=2*pi*100*0.08=16*pi 欧姆。Irms=100/(16*pi)=1.98944 A，Im=sqrt(2)*Irms=2.81349 A。",
        "unit_reason": "所求电流振幅是一个完整结果，必须联合完成感抗计算与有效值到振幅的换算。",
        "concept_blocks": [],
        "limitations": [
          "选择结果不能证明独立写出正弦电流表达式。"
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "b"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "incorrect",
            "derivation": "100/(2*pi*100*0.08)=1.98944 A 是电流有效值。",
            "misconception": "将有效值电压除以感抗得到的量直接当作振幅，漏掉 sqrt(2)。"
          },
          {
            "option_id": "b",
            "truth": "correct",
            "derivation": "Im=sqrt(2)*100/(2*pi*100*0.08)=2.81349 A。",
            "misconception": null
          },
          {
            "option_id": "c",
            "truth": "incorrect",
            "derivation": "使用 XL=nu*L=8 欧姆，计算 Im=sqrt(2)*100/8=17.6777 A。",
            "misconception": "把以赫兹计的频率直接用作角频率。"
          },
          {
            "option_id": "d",
            "truth": "incorrect",
            "derivation": "算出 Irms=1.98944 A 后再除以 sqrt(2)，得到 1.40674 A。",
            "misconception": "颠倒正弦量有效值和振幅的大小关系。"
          }
        ]
      }
    },
    {
      "id": "t15-series-lc-impedance",
      "source_numbers": [
        "7"
      ],
      "intent": {
        "task": "由方向相反的感抗与容抗求串联电路总阻抗。",
        "source_solution": "XL=314.159 欧姆，XC=159.155 欧姆；Z=j(XL-XC)，所以 |Z|=155.004 欧姆。",
        "unit_reason": "保留完整总阻抗任务，必须判断两个串联电抗相减，不分开询问各元件数值。",
        "concept_blocks": [],
        "limitations": [
          "选择数值不能证明独立绘制阻抗相量或写出推导。"
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "c"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "incorrect",
            "derivation": "把两个电抗大小相加，XL+XC=314.159+159.155=473.314 欧姆。",
            "misconception": "把相反方向的电抗电压相量当成同方向。"
          },
          {
            "option_id": "b",
            "truth": "incorrect",
            "derivation": "使用 sqrt(XL^2+XC^2) 得到约 352 欧姆，而非电抗之差。",
            "misconception": "把感抗与容抗当作相互垂直，而不是在虚轴上方向相反。"
          },
          {
            "option_id": "c",
            "truth": "correct",
            "derivation": "电阻为零时 |Z|=abs(2*pi*1000*0.05-1/(2*pi*1000*10^-6))=155.004 欧姆。",
            "misconception": null
          },
          {
            "option_id": "d",
            "truth": "incorrect",
            "derivation": "只计算 XL=2*pi*1000*0.05=314.159 欧姆。",
            "misconception": "忽略串联电容器的非零容抗。"
          }
        ]
      }
    },
    {
      "id": "t15-power-phase",
      "source_numbers": [
        "8"
      ],
      "intent": {
        "task": "从正弦交流振幅和平均功率确定相位差大小，不推断超前或滞后。",
        "source_solution": "P=(Um*Im/2)*cos(phi)，cos(phi)=8000/10000=0.8，|phi|=acos(0.8)=36.8699 度。正负相位差具有相同功率因数。",
        "unit_reason": "一个相位差大小完整检验平均功率推理；数据不确定其符号，故不设超前或滞后的判断任务。",
        "concept_blocks": [],
        "limitations": [
          "源数据不确定相位差符号，不作超前或滞后结论。",
          "选择结果不能证明独立推导平均功率恒等式。"
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "d"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "incorrect",
            "derivation": "误用 cos(phi)=P/(Um*Im)=8000/20000=0.4，得到 acos(0.4)=66.4218 度。",
            "misconception": "把两个振幅作为有效值，漏掉平均乘积中的 1/2。"
          },
          {
            "option_id": "b",
            "truth": "incorrect",
            "derivation": "正确算出比值 0.8，却解 sin(phi)=0.8，得到 asin(0.8)=53.1301 度。",
            "misconception": "把功率因数中的余弦误换成正弦。"
          },
          {
            "option_id": "c",
            "truth": "incorrect",
            "derivation": "假定功率因数为一和 phi=0，会预测 P=Um*Im/2=10000 W，与 8000 W 不符。",
            "misconception": "无视给定非单位功率比，擅自假定负载纯电阻。"
          },
          {
            "option_id": "d",
            "truth": "correct",
            "derivation": "有效值电压与电流乘积为 (Um/sqrt(2))*(Im/sqrt(2))=10000 VA；cos(phi)=0.8，相位差大小为 36.8699 度。",
            "misconception": null
          }
        ]
      }
    },
    {
      "id": "t15-dc-ac-winding",
      "source_numbers": [
        "9"
      ],
      "intent": {
        "task": "比较同一电阻电感绕组在直流稳态与交流稳态的电流。",
        "source_solution": "直流稳态的电感电压为零，I=20/100=0.200 A。400 Hz 时 XL=1600*pi 欧姆，|Z|=sqrt(100^2+(1600*pi)^2)=5027.543 欧姆，Iac,rms=20/|Z|=3.97809 mA。可选交流振幅为 5.62586 mA。",
        "unit_reason": "保留直流与交流电流的完整比较：电源电压数值相同，电流却因电感的频率响应而明显不同。",
        "concept_blocks": [],
        "limitations": [
          "内部推导了可选交流电流振幅，但不单独检验其报出；选择结果不证明独立推导 RL 阻抗。"
        ],
        "figure_observations": []
      },
      "key": {
        "correct": [
          "a"
        ],
        "rationales": [
          {
            "option_id": "a",
            "truth": "correct",
            "derivation": "直流电流为 0.200 A；交流有效值为 20/sqrt(100^2+(2*pi*400*2)^2)=3.97809 mA。",
            "misconception": null
          },
          {
            "option_id": "b",
            "truth": "incorrect",
            "derivation": "保留正确直流值，将交流有效值 3.97809 mA 乘 sqrt(2)，得到振幅 5.62586 mA。",
            "misconception": "在明确要求有效值的位置填入交流电流振幅。"
          },
          {
            "option_id": "c",
            "truth": "incorrect",
            "derivation": "对直流和交流都使用 I=20/R=0.200 A。",
            "misconception": "将直流稳态电感电压消失的结论推广到非零频率交流。"
          },
          {
            "option_id": "d",
            "truth": "incorrect",
            "derivation": "对两个电源都使用 400 Hz 的阻抗 sqrt(R^2+(2*pi*400*L)^2)，两次都得 3.97809 mA。",
            "misconception": "把交流电源频率带入直流稳态计算。"
          }
        ]
      }
    },
    {
      "id": "t15-resonance-phasors",
      "source_numbers": [
        "10"
      ],
      "intent": {
        "task": "按明确的极性与相位约定，识别实际串联共振电路中公共电流、电源以及所有元件电压的完整关系。",
        "source_solution": "实际 SVG 是单一串联 C-R-L 通路，电源标注余弦电压。共振时 XL=XC，各元件电流均为 I。按 exp(j*omega*t)，I 向右，UR=RI 向右，UL=jXL*I 向上，UC=-jXC*I 向下，两个电抗电压大小相等。U_source=UR+UL+UC=UR。图中电阻仍在，故相消的是电抗电压之和，而非各元件电压分别为零。",
        "unit_reason": "一个原生多选题同时判断整个相位关系网络，覆盖电源与每个元件，不拆成逐箭头是非题或组合编码选项。",
        "concept_blocks": [],
        "limitations": [
          "识别完整相位关系不能证明独立绘制、按比例安排及空间标注电流和电压相量图。",
          "源图没有极性箭头，所以电源端子与元件被动电压参考方向在题面明确约定，不能称为源图观察所得。",
          "原始材料只提供电路图，不提供相量图；没有虚构源相量图或新候选插图。"
        ],
        "figure_observations": [
